 public static class QuestRules319 {
  public static readonly string[] Names={"基地指挥官","医疗负责人","工程师","军事企业代表","后勤主管"};
  public static readonly string[] Roles={"主线与每日行动委托","医疗补给与救援合作","工作台升级资格与技术合作","武器弹药图纸与配件合作","物资回收与基础保障"};
  // Authored harbor road/waiting-area candidates; resolve to a reachable point in their own search circle.
  public static readonly QuestPoint319[] Points={new QuestPoint319("entry","入口区调查台","investigate",-8,-49,8),new QuestPoint319("yard","后勤院北门救援点","rescue",-49,-22,12),new QuestPoint319("repair","维修区外围投放台","place",-26,2,12),new QuestPoint319("cargo","集装箱区道路调查台","investigate",20,34,14),new QuestPoint319("dock","南部码头救援点","rescue",101,-47,12),new QuestPoint319("north","北侧道路投放台","place",-17,61,15)};
  public static QuestPoint319 Point(string id)=>Array.Find(Points,p=>p.Id==id);
  public static int Level(NpcSave319 s,int npc)=>NpcProduction328.RelationshipLevel(s,npc);
  public static string TypeName(QuestType319 t)=>new[]{"收集","战斗","调查","放置","救援"}[(int)t];
  public static long DayAt(DateTime utc)=>(long)(utc.ToUniversalTime().AddHours(8).AddHours(-5).Date-new DateTime(2020,1,1)).TotalDays;
  public static long WeekAt(long day){var date=new DateTime(2020,1,1).AddDays(day);return day-((int)date.DayOfWeek+6)%7;}
  static Quest319 Q(string template,string title,int npc,QuestType319 type,int count,int difficulty=0,CollectionCategory category=CollectionCategory.None,string point="",bool evac=false,int enemy=0){return new Quest319{Template=template,Id="long:"+template,Title=title,Npc=npc,Type=type,Required=count,Difficulty=difficulty,Category=category,PointId=point,Evacuate=evac,EnemyFilter=enemy,Coins=400+difficulty*350,XP=0,Description=type==QuestType319.Collect?"向联系人上交仓库中的已认证收藏品。":type==QuestType319.Kill?"在正式港口行动中击败目标敌人。":type==QuestType319.Place?"从本局搜集所需收藏品，到投放台长按F提交。":type==QuestType319.Rescue?"到救援点长按F联系待救援人员，再成功撤离。":"到目标区域找到调查台，长按F调查。"};}
  public static List<Quest319> LongTasks(){var rows=new List<Quest319>{Q("cmd-entry","主线01 · 确认入口通道",0,QuestType319.Investigate,1,0,point:"entry",evac:true),Q("cmd-patrol","主线02 · 清理港口威胁",0,QuestType319.Kill,4,1),Q("cmd-rescue","主线03 · 建立救援通道",0,QuestType319.Rescue,1,1,point:"dock",evac:true)};rows[1].Predecessor=rows[0].Id;rows[2].Predecessor=rows[1].Id;rows[0].Reward=ItemKind.GreenArmorKit;rows[0].RewardCount=1;rows[1].Reward=ItemKind.GreenAmmo;rows[1].RewardCount=30;rows[2].Reward=ItemKind.ArmorKit;rows[2].RewardCount=1;
   rows.Add(Q("med-samples","合作01 · 回收医疗材料",1,QuestType319.Collect,2,0,CollectionCategory.MedicalMaterials));rows.Add(Q("med-rescue","合作02 · 接应院外人员",1,QuestType319.Rescue,1,1,point:"yard",evac:true));rows[4].Predecessor=rows[3].Id;rows[4].Reward=ItemKind.ArmorKit;rows[4].RewardCount=1;
   rows.Add(Q("eng-parts","合作01 · 工具零件回收",2,QuestType319.Collect,3,0,CollectionCategory.ToolsParts));rows.Add(Q("eng-survey","合作02 · 核查货运设施",2,QuestType319.Investigate,1,1,point:"cargo",evac:true));rows[6].Predecessor=rows[5].Id;rows[6].Reward=ItemKind.GreenForegrip30;rows[6].RewardCount=1;
   rows.Add(Q("mil-clear","合作01 · 清除叛军巡逻",3,QuestType319.Kill,3,0,enemy:1));rows.Add(Q("mil-electronics","合作02 · 回收电子零件",3,QuestType319.Collect,2,1,CollectionCategory.Electronics));rows[8].Predecessor=rows[7].Id;rows[8].Reward=ItemKind.GreenAmmo;rows[8].RewardCount=60;
   rows.Add(Q("log-living","合作01 · 回收生活物资",4,QuestType319.Collect,3,0,CollectionCategory.Living));rows.Add(Q("log-delivery","合作02 · 修复外围补给点",4,QuestType319.Place,2,1,CollectionCategory.ToolsParts,"repair",true));rows[10].Predecessor=rows[9].Id;rows[10].Reward=ItemKind.SmallPack;rows[10].RewardCount=1;
   var medical=Q("med-followup","合作03 · 医疗备品补充",1,QuestType319.Collect,3,1,CollectionCategory.MedicalMaterials);medical.Predecessor="long:med-rescue";medical.Reward=ItemKind.ArmorKit;medical.RewardCount=1;rows.Add(medical);
   var engineer=Q("eng-inspection","合作03 · 复核入口设施",2,QuestType319.Investigate,1,1,point:"entry",evac:true);engineer.Predecessor="long:eng-survey";engineer.Reward=ItemKind.GreenForegrip30;engineer.RewardCount=1;rows.Add(engineer);
   var military=Q("mil-secure","合作03 · 巩固货运通道",3,QuestType319.Kill,4,1,enemy:1);military.Predecessor="long:mil-electronics";military.Reward=ItemKind.Ammo;military.RewardCount=60;rows.Add(military);
   var logistics=Q("log-assist","合作03 · 接应后勤人员",4,QuestType319.Rescue,1,1,point:"yard",evac:true);logistics.Predecessor="long:log-delivery";logistics.Reward=ItemKind.SmallRig;logistics.RewardCount=1;rows.Add(logistics);
   foreach(var q in rows){q.XP=0;var unlock=NpcProduction328.UnlockText(q);if(unlock.Length>0)q.Description+=" 领取奖励后解锁："+unlock+"。";}return rows;
  }
  static List<Quest319> Pool(int difficulty){if(difficulty==0)return new List<Quest319>{Q("life","生活物资回收",0,QuestType319.Collect,2,0,CollectionCategory.Living),Q("parts","工具零件回收",0,QuestType319.Collect,2,0,CollectionCategory.ToolsParts),Q("patrol","外围威胁清理",0,QuestType319.Kill,2),Q("entry-check","入口通道调查",0,QuestType319.Investigate,1,point:"entry",evac:true),Q("biology","异种样本回收",0,QuestType319.Collect,2,0,CollectionCategory.Biological)};if(difficulty==1)return new List<Quest319>{Q("rebel","叛军巡逻清理",0,QuestType319.Kill,3,1,enemy:1),Q("supply","外围补给投放",0,QuestType319.Place,1,1,CollectionCategory.ToolsParts,"repair",true),Q("yard-aid","后勤院外围救援",0,QuestType319.Rescue,1,1,point:"yard",evac:true),Q("cargo-check","货运道路调查",0,QuestType319.Investigate,1,1,point:"cargo",evac:true)};return new List<Quest319>{Q("dock-aid","码头人员接应",0,QuestType319.Rescue,1,2,point:"dock",evac:true),Q("north-supply","北侧道路补给",0,QuestType319.Place,2,2,CollectionCategory.ToolsParts,"north",true),Q("single-clear","单局异种清理",0,QuestType319.Kill,4,2,evac:true,enemy:2)};}
  public static List<Quest319> DailyTasks(long day,long week){var rng=new System.Random(unchecked((int)day*7919+319));var rows=new List<Quest319>();for(int i=0;i<5;i++){var pool=Pool(i<3?0:i==3?1:2);pool.RemoveAll(q=>rows.Exists(p=>p.Template==q.Template));var q=pool[rng.Next(pool.Count)];q.Id="daily:"+day+":"+i+":"+q.Template;q.Period="daily";q.Day=day;q.Week=week;q.SingleRaid=q.Template=="single-clear";rows.Add(q);}for(int npc=1;npc<5;npc++){var cats=new[]{CollectionCategory.None,CollectionCategory.MedicalMaterials,CollectionCategory.ToolsParts,CollectionCategory.Electronics,CollectionCategory.Living};var q=Q("cooperation-"+npc,"每日 · "+RaidInventory.CategoryName(cats[npc])+"回收",npc,QuestType319.Collect,2);q.Category=cats[npc];q.Id="daily:"+day+":npc:"+npc;q.Period="daily";q.Day=day;q.Week=week;rows.Add(q);}return rows;}
  public static readonly Exchange319[] ExchangePool={new Exchange319("med-basic","医疗材料换简易甲包",1,1,CollectionCategory.MedicalMaterials,2,ItemKind.GreenArmorKit,1),new Exchange319("med-biological","异种样本换简易甲包",1,1,CollectionCategory.Biological,3,ItemKind.GreenArmorKit,1),new Exchange319("med-advanced","医疗合作标准甲包",1,2,CollectionCategory.MedicalMaterials,4,ItemKind.ArmorKit,1),new Exchange319("eng-tools","工具零件换枪械零件",2,1,CollectionCategory.ToolsParts,2,ItemKind.GunParts,2),new Exchange319("eng-power","能源材料换弹药",2,1,CollectionCategory.EnergyChemicals,2,ItemKind.GreenAmmo,50),new Exchange319("eng-mod","技术合作握把",2,2,CollectionCategory.Electronics,3,ItemKind.GreenForegrip30,1),new Exchange319("mil-ammo","电子材料换步枪弹",3,1,CollectionCategory.Electronics,2,ItemKind.GreenAmmo,60),new Exchange319("mil-pistol","生物样本换9毫米弹",3,1,CollectionCategory.Biological,3,ItemKind.Green9mm,60),new Exchange319("mil-mod","军工合作蓝色枪口",3,2,CollectionCategory.Electronics,4,ItemKind.BlueMuzzle30,1),new Exchange319("log-med","生活物资换简易甲包",4,1,CollectionCategory.Living,2,ItemKind.GreenArmorKit,1),new Exchange319("log-pack","生活物资换轻型背包",4,1,CollectionCategory.Living,4,ItemKind.SmallPack,1),new Exchange319("log-armor","后勤合作蓝色防具",4,2,CollectionCategory.ToolsParts,5,ItemKind.BlueArmor,1)};
  public static List<Exchange319> DailyExchanges(long day,int npc){var pool=new List<Exchange319>(Array.FindAll(ExchangePool,e=>e.Npc==npc));var rng=new System.Random(unchecked((int)day*3571+npc*139));var rows=new List<Exchange319>();while(rows.Count<2&&pool.Count>0){int i=rng.Next(pool.Count);rows.Add(pool[i]);pool.RemoveAt(i);}return rows;}
  public static bool Available(NpcSave319 s,Quest319 q)=>!q.Expired&&(string.IsNullOrEmpty(q.Predecessor)||s.Quests.Exists(p=>p.Id==q.Predecessor&&p.Completed));
  public static int CountMaterials(BaseSave s,CollectionCategory category,bool certified){int n=0;foreach(var p in s.Warehouse)if(Certification319.Collection(p.Kind)&&RaidInventory.Category(p.Kind)==category&&(!certified||p.Origin==ItemOrigin.Certified))n+=p.Count;return n;}
  public static bool SpendMaterials(BaseSave s,CollectionCategory category,int count,bool certified){if(CountMaterials(s,category,certified)<count)return false;var ordered=s.Warehouse.FindAll(p=>Certification319.Collection(p.Kind)&&RaidInventory.Category(p.Kind)==category&&(!certified||p.Origin==ItemOrigin.Certified));ordered.Sort((a,b)=>RaidInventory.Value(a).CompareTo(RaidInventory.Value(b)));foreach(var p in ordered){if(count==0)break;if(!Certification319.Collection(p.Kind)||RaidInventory.Category(p.Kind)!=category||certified&&p.Origin!=ItemOrigin.Certified)continue;int n=Math.Min(count,p.Count);p.Count-=n;count-=n;if(p.Count==0)s.Warehouse.Remove(p);}return count==0;}
  public static void Complete(NpcSave319 s,Quest319 q){if(q.Completed)return;q.Progress=q.Required;q.Completed=true;if(q.Npc==0&&q.Period=="daily"&&!q.Counted){q.Counted=true;if(q.Week==s.Week){s.WeekCompleted++;if(s.WeekCompleted>=10)s.EarnedForWeek=s.Week+7;}}}
  public static void Refresh(BaseSave save,long nowDay){save.Npc319=save.Npc319??new NpcSave319();var s=save.Npc319;NpcProduction328.Normalize(save);long day=Math.Max(nowDay,s.LastDay),week=WeekAt(day);if(s.Initialized&&s.Day==day)return;if(!s.Initialized){s.Initialized=true;s.Week=week;}if(s.Week!=week){s.SafeRows=s.EarnedForWeek==week?3:2;s.WeekCompleted=0;s.Week=week;}foreach(var q in s.Quests)if(q.Period=="daily"&&q.Day!=day&&!q.Completed){q.Expired=true;q.Accepted=false;}s.Quests.RemoveAll(q=>q.Period=="daily"&&(q.Expired||q.Claimed&&q.Day!=day));s.Quests.AddRange(DailyTasks(day,week));foreach(var q in s.Quests)q.XP=0;s.Exchanges.RemoveAll(e=>e.Day!=day);s.Day=s.LastDay=day;}
  public static void Normalize(BaseSave save,long day){save.Npc319=save.Npc319??new NpcSave319();var s=save.Npc319;s.Quests=s.Quests??new List<Quest319>();s.Exchanges=s.Exchanges??new List<ExchangeUse319>();s.PendingItems=s.PendingItems??new List<ItemStack>();if(s.XP==null||s.XP.Length!=5)Array.Resize(ref s.XP,5);Refresh(save,day);s.SafeRows=s.SafeRows==3?3:2;ResizeSafe(save);}
  public static void ResizeSafe(BaseSave save){var target=new RaidInventory(2,save.Npc319.SafeRows);foreach(var p in save.SafeItems){var copy=RaidInventory.Copy(p);if(copy==null)continue;int remaining=target.Add(copy);if(remaining>0){copy.Count=remaining;var warehouse=CampRules.Grid(save);int left=warehouse.Add(copy);if(left>0){copy.Count=left;save.Npc319.PendingItems.Add(copy);}}}save.SafeItems=target.Snapshot();}
 }
